SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "+00:00";
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS security_company_db
  CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE security_company_db;

DROP TABLE IF EXISTS payroll_contributions;
DROP TABLE IF EXISTS payroll;
DROP TABLE IF EXISTS evaluations;
DROP TABLE IF EXISTS leave_requests;
DROP TABLE IF EXISTS deployments;
DROP TABLE IF EXISTS employees;
DROP TABLE IF EXISTS clients;
DROP TABLE IF EXISTS addresses;
DROP TABLE IF EXISTS user_accounts;
DROP TABLE IF EXISTS user_roles;

CREATE TABLE user_roles (
  user_role_id INT NOT NULL PRIMARY KEY,
  user_role_name VARCHAR(100) NOT NULL,
  description VARCHAR(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE user_accounts (
  user_id INT NOT NULL PRIMARY KEY,
  user_role_id INT NOT NULL,
  username VARCHAR(60) NOT NULL UNIQUE,
  email VARCHAR(150) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  created_at DATETIME NOT NULL,
  last_login DATETIME DEFAULT NULL,
  account_status ENUM('Active','Disabled','Locked') NOT NULL DEFAULT 'Active',
  CONSTRAINT fk_users_roles FOREIGN KEY (user_role_id) REFERENCES user_roles(user_role_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE addresses (
  address_id INT NOT NULL PRIMARY KEY,
  street VARCHAR(150) DEFAULT NULL,
  barangay VARCHAR(100) DEFAULT NULL,
  city_or_municipality VARCHAR(100) NOT NULL,
  province VARCHAR(100) NOT NULL,
  region VARCHAR(100) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE clients (
  client_id INT NOT NULL PRIMARY KEY,
  company_name VARCHAR(150) NOT NULL,
  contact_person VARCHAR(120) NOT NULL,
  contact_number VARCHAR(20) NOT NULL,
  address_id INT NOT NULL,
  contract_start DATE NOT NULL,
  contract_end DATE DEFAULT NULL,
  client_status ENUM('Active','Inactive','Pending') NOT NULL DEFAULT 'Active',
  CONSTRAINT fk_clients_address FOREIGN KEY (address_id) REFERENCES addresses(address_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE employees (
  employee_id INT NOT NULL PRIMARY KEY,
  user_id INT DEFAULT NULL,
  address_id INT NOT NULL,
  employee_code VARCHAR(20) NOT NULL UNIQUE,
  first_name VARCHAR(80) NOT NULL,
  middle_name VARCHAR(80) DEFAULT NULL,
  last_name VARCHAR(80) NOT NULL,
  gender ENUM('Male','Female','Prefer not to say') NOT NULL,
  phone VARCHAR(20) NOT NULL,
  birth_date DATE NOT NULL,
  hire_date DATE NOT NULL,
  department VARCHAR(80) NOT NULL,
  job_title VARCHAR(100) NOT NULL,
  monthly_salary DECIMAL(10,2) NOT NULL,
  employment_status ENUM('Active','Inactive','On Leave') NOT NULL DEFAULT 'Active',
  CONSTRAINT fk_employees_user FOREIGN KEY (user_id) REFERENCES user_accounts(user_id),
  CONSTRAINT fk_employees_address FOREIGN KEY (address_id) REFERENCES addresses(address_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE deployments (
  deployment_id INT NOT NULL PRIMARY KEY,
  employee_id INT NOT NULL,
  client_id INT NOT NULL,
  post_name VARCHAR(100) NOT NULL,
  duty_description VARCHAR(255) NOT NULL,
  shift_name ENUM('Day Shift','Night Shift','Rotating Shift') NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE DEFAULT NULL,
  deployment_status ENUM('Scheduled','Active','Completed','Cancelled') NOT NULL DEFAULT 'Active',
  CONSTRAINT fk_deploy_employee FOREIGN KEY (employee_id) REFERENCES employees(employee_id),
  CONSTRAINT fk_deploy_client FOREIGN KEY (client_id) REFERENCES clients(client_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE leave_requests (
  leave_id INT NOT NULL PRIMARY KEY,
  employee_id INT NOT NULL,
  leave_type VARCHAR(60) NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  reason VARCHAR(255) DEFAULT NULL,
  approval_status ENUM('Pending','Approved','Rejected') NOT NULL DEFAULT 'Pending',
  filed_at DATETIME NOT NULL,
  CONSTRAINT fk_leave_employee FOREIGN KEY (employee_id) REFERENCES employees(employee_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE evaluations (
  evaluation_id INT NOT NULL PRIMARY KEY,
  employee_id INT NOT NULL,
  evaluator_name VARCHAR(120) NOT NULL,
  evaluation_date DATE NOT NULL,
  punctuality DECIMAL(4,2) NOT NULL,
  performance DECIMAL(4,2) NOT NULL,
  conduct DECIMAL(4,2) NOT NULL,
  remarks VARCHAR(255) DEFAULT NULL,
  CONSTRAINT fk_eval_employee FOREIGN KEY (employee_id) REFERENCES employees(employee_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE payroll (
  payroll_id INT NOT NULL PRIMARY KEY,
  employee_id INT NOT NULL,
  payroll_month DATE NOT NULL,
  basic_salary DECIMAL(10,2) NOT NULL,
  overtime_pay DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  deductions DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  net_pay DECIMAL(10,2) NOT NULL,
  payment_status ENUM('Pending','Paid','On Hold') NOT NULL DEFAULT 'Pending',
  paid_at DATETIME DEFAULT NULL,
  CONSTRAINT fk_payroll_employee FOREIGN KEY (employee_id) REFERENCES employees(employee_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE payroll_contributions (
  contribution_id INT NOT NULL PRIMARY KEY,
  payroll_id INT NOT NULL,
  contribution_type VARCHAR(60) NOT NULL,
  contribution_amount DECIMAL(10,2) NOT NULL,
  recorded_at DATE NOT NULL,
  CONSTRAINT fk_contrib_payroll FOREIGN KEY (payroll_id) REFERENCES payroll(payroll_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

