-- Helpful verification queries
SHOW TABLES;
SELECT COUNT(*) AS total_addresses FROM addresses;
SELECT COUNT(*) AS total_users FROM user_accounts;
SELECT COUNT(*) AS total_clients FROM clients;
SELECT COUNT(*) AS total_employees FROM employees;
SELECT COUNT(*) AS total_deployments FROM deployments;
SELECT COUNT(*) AS total_leave_requests FROM leave_requests;
SELECT COUNT(*) AS total_evaluations FROM evaluations;
SELECT COUNT(*) AS total_payroll_records FROM payroll;
SELECT COUNT(*) AS total_contributions FROM payroll_contributions;

-- Example INNER JOIN
SELECT e.employee_code, e.first_name, e.last_name, d.post_name, c.company_name
FROM employees AS e
INNER JOIN deployments AS d ON e.employee_id = d.employee_id
INNER JOIN clients AS c ON d.client_id = c.client_id
LIMIT 50;

-- Example numeric filters
SELECT employee_code, first_name, last_name, monthly_salary
FROM employees
WHERE monthly_salary > 20000
ORDER BY monthly_salary DESC;

SELECT payroll_id, employee_id, net_pay, payment_status
FROM payroll
WHERE net_pay < 16000
ORDER BY net_pay ASC
LIMIT 100;

SET FOREIGN_KEY_CHECKS = 1;
